import gzip,collections
IUPAC={'A':'A','C':'C','G':'G','T':'T','R':'AG','Y':'CT','M':'AC','W':'AT','S':'GC','K':'GT','B':'CGT','D':'AGT','H':'ACT','V':'ACG','N':'ACGT'}
def regex(s): return ''.join('['+''.join(IUPAC[c])+']' if len(IUPAC[c])>1 else c for c in s)
def rc(s): return s.translate(str.maketrans('ACGT','TGCA'))[::-1]
pats={'F':re.compile(regex('GTGYCAGCMGCCGCGGTAA')),'R':re.compile(regex('GGACTACNVGGGTWTCTAAT'))}
comb=collections.Counter(); off=collections.Counter()
for s in [f'S{i:02d}' for i in range(1,12)]:
    files=[gzip.open(f'/task/input/fastq/{s}_R{x}.fastq.gz','rt') for x in (1,2)]
    while True:
        heads=[]
        for f in files:
            h=f.readline()
            if not h: break
            h=h.strip(); seq=f.readline().strip(); f.readline(); f.readline()
            heads.append((h,seq))
        if len(heads)<2: break
        if heads[0][0].split()[0]!=heads[1][0].split()[0]:
            raise RuntimeError('unpaired: '+str(heads))
        labels=[]
        for h,seq in heads:
            found=[k for k,cp in pats.items() if cp.search(seq[:26])]
            labels.append(''.join(found) or '-')
        comb[tuple(labels)]+=1
        off[(next((pats['F'].search(heads[0][1][:26]).start()) if 'F' in labels[0] else -1,-2),next((pats['F'].search(heads[1][1][:26]).start()) if 'F' in labels[1] else -1,-2))]+=1
    for f in files: f.close()
print('pair orientation patterns',comb)
print('forward offset patterns',off)
